//! Build script: embeds the application icon and the version information in the Windows executable
//! The icon is generated by `assets/icon/generate_icon.py`.

// No `Result` return type: on a non-Windows host the block below is compiled out, nothing can fail
// any more, and clippy (run on Linux by the CI) rejects it with `unnecessary_wraps`.
fn main() {
    // Without any `rerun-if-changed` line, Cargo reruns a build script as soon as any file of the
    // package changes, so every edit in src/ would recompile the resources for nothing. Once at
    // least one line is printed, Cargo only watches the listed paths: the files read below.
    // winresource prints none itself. build.rs needs no line: Cargo always recompiles and reruns
    // a build script whose own source changed.
    println!("cargo:rerun-if-changed=assets/icon/rsnake.ico");
    println!("cargo:rerun-if-changed=Cargo.toml");

    #[cfg(windows)]
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows") {
        // `WindowsResource::new()` fills the version information of the executable (file properties,
        // "Details" tab) from Cargo.toml
        // Each string can be replaced with `set()` as below, or from a
        // `[package.metadata.winresource]` table in Cargo.toml (e.g. LegalCopyright = "...").
        let mut resource = winresource::WindowsResource::new();
        resource.set_icon("assets/icon/rsnake.ico");
        resource.set("LegalCopyright", "GPL-3.0-only");
        //English langage
        resource.set_language(0x0009);
        resource.set("Comments", "Enjoy your game !");
        resource
            .compile()
            .expect("the Windows resources (icon, version information) should compile");
    }
}
